     1	/**
     2	 * Project lifecycle including the project-count quota and the cascade that archives a project's issues.
     3	 *
     4	 * Must call (do not reimplement): assertCan, assertOrgScope, emit, wouldExceedLimit, uniqueSlug, projectKeyFromName
     5	 */
     6	import { wouldExceedLimit } from "@/config/plan-limits";
     7	import { emit } from "@/lib/event-bus";
     8	import { assertCan } from "@/lib/permissions";
     9	import { projectKeyFromName, uniqueSlug } from "@/lib/slug";
    10	import { assertNotArchived } from "@/lib/soft-delete";
    11	import { assertOrgScope } from "@/lib/tenant";
    12	import * as issueRepo from "@/server/repositories/issue-repository";
    13	import * as orgRepo from "@/server/repositories/organization-repository";
    14	import * as projectRepo from "@/server/repositories/project-repository";
    15	import {
    16	  actorEnvelope,
    17	  orgResource,
    18	  projectResource,
    19	  requireFound,
    20	} from "./_support";
    21	import type {
    22	  ArchiveProjectInput,
    23	  CreateProjectInput,
    24	  ListProjectsInput,
    25	  UpdateProjectInput,
    26	} from "@/schemas/project";
    27	import type { OrgId, Page, ProjectId } from "@/types/common";
    28	import type { Actor } from "@/types/member";
    29	import type { Project, ProjectWithStats } from "@/types/project";
    30	
    31	/**
    32	 * Creates a project once the plan still has room for one. The key is derived
    33	 * from the name when the caller left it blank, so the issue numbering scheme
    34	 * (`TF-12`) is never invented at the call site.
    35	 *
    36	 * The ops console duplicates a project with `projectRepo.duplicateProject`
    37	 * plus `issueRepo.copyIssuesToProject`; those bypass the gates below.
    38	 */
    39	export async function createProject(
    40	  actor: Actor,
    41	  input: CreateProjectInput,
    42	): Promise<Project> {
    43	  assertOrgScope(actor, input.orgId);
    44	  assertCan(actor, "project:create", orgResource(input.orgId));
    45	
    46	  const org = requireFound(
    47	    await orgRepo.findOrgById(input.orgId),
    48	    "Organization",
    49	    input.orgId,
    50	  );
    51	
    52	  const used = await projectRepo.countProjects(input.orgId);
    53	  if (wouldExceedLimit(org.plan, "projects", used)) {
    54	    throw new Error(
    55	      `Plan ${org.plan} allows ${used} projects; upgrade to add another`,
    56	    );
    57	  }
    58	
    59	  const slug = await suggestProjectSlug(input.orgId, input.name);
    60	
    61	  const project = await projectRepo.insertProject({
    62	    ...input,
    63	    slug,
    64	    key: input.key || projectKeyFromName(input.name),
    65	  });
    66	
    67	  await emit("project.created", {
    68	    ...actorEnvelope(actor),
    69	    projectId: project.id,
    70	    name: project.name,
    71	    slug: project.slug,
    72	  });
    73	
    74	  return project;
    75	}
    76	
    77	export async function updateProject(
    78	  actor: Actor,
    79	  input: UpdateProjectInput,
    80	): Promise<Project> {
    81	  assertOrgScope(actor, input.orgId);
    82	
    83	  const project = requireFound(
    84	    await projectRepo.findProjectById(input.orgId, input.projectId),
    85	    "Project",
    86	    input.projectId,
    87	  );
    88	  assertCan(actor, "project:update", projectResource(project));
    89	  assertNotArchived("Project", project.id, project);
    90	
    91	  return projectRepo.updateProject(input);
    92	}
    93	
    94	/**
    95	 * Archiving a project cascades to its issues by default — leaving live issues
    96	 * behind an archived project is the drift this flag exists to prevent.
    97	 */
    98	export async function archiveProject(
    99	  actor: Actor,
   100	  input: ArchiveProjectInput,
   101	): Promise<Project> {
   102	  assertOrgScope(actor, input.orgId);
   103	
   104	  const project = requireFound(
   105	    await projectRepo.findProjectById(input.orgId, input.projectId),
   106	    "Project",
   107	    input.projectId,
   108	  );
   109	  assertCan(actor, "project:archive", projectResource(project));
   110	  assertNotArchived("Project", project.id, project);
   111	
   112	  const issuesArchived = input.archiveIssues
   113	    ? await issueRepo.archiveIssuesForProject(input.orgId, input.projectId)
   114	    : 0;
   115	
   116	  const archived = await projectRepo.archiveProject(
   117	    input.orgId,
   118	    input.projectId,
   119	  );
   120	
   121	  await emit("project.archived", {
   122	    ...actorEnvelope(actor),
   123	    projectId: archived.id,
   124	    issuesArchived,
   125	  });
   126	
   127	  return archived;
   128	}
   129	
   130	/** Restore does not un-archive the issues: they are restored individually. */
   131	export async function restoreProject(
   132	  actor: Actor,
   133	  orgId: OrgId,
   134	  projectId: ProjectId,
   135	): Promise<Project> {
   136	  assertOrgScope(actor, orgId);
   137	
   138	  const project = requireFound(
   139	    await projectRepo.findProjectById(orgId, projectId),
   140	    "Project",
   141	    projectId,
   142	  );
   143	  assertCan(actor, "project:archive", projectResource(project));
   144	
   145	  const restored = await projectRepo.restoreProject(orgId, projectId);
   146	
   147	  await emit("project.restored", {
   148	    ...actorEnvelope(actor),
   149	    projectId: restored.id,
   150	  });
   151	
   152	  return restored;
   153	}
   154	
   155	export async function getProject(
   156	  actor: Actor,
   157	  orgId: OrgId,
   158	  slug: string,
   159	): Promise<ProjectWithStats> {
   160	  assertOrgScope(actor, orgId);
   161	
   162	  const project = requireFound(
   163	    await projectRepo.findProjectBySlug(orgId, slug),
   164	    "Project",
   165	    slug,
   166	  );
   167	  assertCan(actor, "project:read", projectResource(project));
   168	
   169	  return {
   170	    project,
   171	    stats: await projectRepo.getProjectStats(orgId, project.id),
   172	  };
   173	}
   174	
   175	export async function listProjects(
   176	  actor: Actor,
   177	  input: ListProjectsInput,
   178	): Promise<Page<ProjectWithStats>> {
   179	  assertOrgScope(actor, input.orgId);
   180	  assertCan(actor, "project:read", orgResource(input.orgId));
   181	
   182	  const page = await projectRepo.listProjects(input);
   183	
   184	  const items = await Promise.all(
   185	    page.items.map(async (project) => ({
   186	      project,
   187	      stats: await projectRepo.getProjectStats(input.orgId, project.id),
   188	    })),
   189	  );
   190	
   191	  return { items, nextCursor: page.nextCursor, total: page.total };
   192	}
   193	
   194	/**
   195	 * Slug preview used by both the create form and `createProject`, so what the
   196	 * user sees while typing is what the row ends up with.
   197	 */
   198	export async function suggestProjectSlug(
   199	  orgId: OrgId,
   200	  name: string,
   201	): Promise<string> {
   202	  const taken = await projectRepo.listTakenProjectSlugs(orgId);
   203	  return uniqueSlug(name, taken);
   204	}

