    31	  name: z.string().min(2).max(80).optional(),
    32	  description: z.string().max(2_000).nullable().optional(),
    33	  visibility: projectVisibilitySchema.optional(),
    34	  status: projectStatusSchema.optional(),
    35	  leadId: userIdSchema.nullable().optional(),
    36	  color: hexColorSchema.optional(),
    37	  targetDate: isoTimestampSchema.nullable().optional(),
    38	});
