    52	    priceCentsPerSeatMonthly: 900,
    53	  },
    54	  growth: {
    55	    plan: "growth",
    56	    seats: 50,
    57	    projects: 100,
    58	    issuesPerProject: 10_000,
    59	    storageMb: 20_000,
    60	    apiRequestsPerHour: 10_000,
    61	    webhooks: 10,
    62	    retentionDays: 365,
