     1	/**
     2	 * Test double for `@/lib/id` (owner E).
     3	 *
     4	 * The server suite needs ids that are valid ULIDs *and* reproducible, so a
     5	 * failing assertion names the same row on every run. Counter-based rather than
     6	 * random for exactly that reason.
     7	 */
     8	const ULID_ALPHABET = "0123456789ABCDEFGHJKMNPQRSTVWXYZ";
     9	const ULID_LENGTH = 26;
    10	
    11	let counter = 0;
    12	
    13	export function newId(): string {
    14	  counter += 1;
    15	  return encode(counter);
    16	}
    17	
    18	export function isUlid(value: string): boolean {
    19	  return (
    20	    value.length === ULID_LENGTH &&
    21	    [...value].every((char) => ULID_ALPHABET.includes(char.toUpperCase()))
    22	  );
    23	}
    24	
    25	export function idFactory(seed: number): () => string {
    26	  let local = seed;
    27	  return () => {
    28	    local += 1;
    29	    return encode(local);
    30	  };
    31	}
    32	
    33	/** Test-only: rewinds the counter so each file starts from the same ids. */
    34	export function resetIds(): void {
    35	  counter = 0;
    36	}
    37	
    38	function encode(value: number): string {
    39	  let remaining = value;
    40	  let out = "";
    41	
    42	  while (out.length < ULID_LENGTH) {
    43	    out = `${ULID_ALPHABET[remaining % 32] ?? "0"}${out}`;
    44	    remaining = Math.floor(remaining / 32);
    45	  }
    46	
    47	  return out.slice(-ULID_LENGTH);
    48	}
