     1	/** Project slug/key validation and the archive scope extension. */
     2	import { describe, expect, it } from "vitest";
     3	import {
     4	  archiveProjectSchema,
     5	  createProjectSchema,
     6	  listProjectsSchema,
     7	  projectStatusSchema,
     8	  projectVisibilitySchema,
     9	  updateProjectSchema,
    10	} from "@/schemas/project";
    11	import { RESERVED_SLUGS } from "@/lib/slug";
    12	import { ORG_A } from "../helpers/factories";
    13	
    14	const PROJECT = "01HZZZPPPPPPPPPPPPPPPPPPPP";
    15	
    16	function createInput(overrides: Record<string, unknown> = {}) {
    17	  return {
    18	    orgId: ORG_A,
    19	    name: "Website relaunch",
    20	    slug: "website-relaunch",
    21	    key: "WEB",
    22	    ...overrides,
    23	  };
    24	}
    25	
    26	describe("schemas/project", () => {
    27	  it("applies the documented defaults", () => {
    28	    expect(createProjectSchema.parse(createInput())).toMatchObject({
    29	      description: null,
    30	      visibility: "org",
    31	      leadId: null,
    32	      color: "#6366f1",
    33	      targetDate: null,
    34	    });
    35	  });
    36	
    37	  it("accepts the visibility and status vocabularies", () => {
    38	    for (const visibility of ["private", "org", "public"]) {
    39	      expect(projectVisibilitySchema.safeParse(visibility).success, visibility).toBe(true);
    40	    }
    41	    for (const status of ["active", "paused", "completed"]) {
    42	      expect(projectStatusSchema.safeParse(status).success, status).toBe(true);
    43	    }
    44	    expect(projectVisibilitySchema.safeParse("secret").success).toBe(false);
    45	  });
    46	
    47	  it("shares the slug rules with @/lib/slug", () => {
    48	    expect(createProjectSchema.safeParse(createInput({ slug: "Website" })).success).toBe(
    49	      false,
    50	    );
    51	    expect(createProjectSchema.safeParse(createInput({ slug: "web--site" })).success).toBe(
    52	      false,
    53	    );
    54	    expect(createProjectSchema.safeParse(createInput({ slug: "a" })).success).toBe(false);
    55	  });
    56	
    57	  it("refuses a reserved slug", () => {
    58	    for (const reserved of RESERVED_SLUGS.slice(0, 5)) {
    59	      const result = createProjectSchema.safeParse(createInput({ slug: reserved }));
    60	      expect(result.success, reserved).toBe(false);
    61	    }
    62	  });
    63	
    64	  it("requires a 2-4 character uppercase project key", () => {
    65	    expect(createProjectSchema.safeParse(createInput({ key: "WEB" })).success).toBe(true);
    66	    expect(createProjectSchema.safeParse(createInput({ key: "W" })).success).toBe(false);
    67	    expect(createProjectSchema.safeParse(createInput({ key: "WEBSITE" })).success).toBe(
    68	      false,
    69	    );
    70	    expect(createProjectSchema.safeParse(createInput({ key: "web" })).success).toBe(false);
    71	    expect(createProjectSchema.safeParse(createInput({ key: "1WE" })).success).toBe(false);
    72	    expect(createProjectSchema.safeParse(createInput({ key: "W3B" })).success).toBe(true);
    73	  });
    74	
    75	  it("requires a #rrggbb colour", () => {
    76	    expect(createProjectSchema.safeParse(createInput({ color: "#abcdef" })).success).toBe(
    77	      true,
    78	    );
    79	    expect(createProjectSchema.safeParse(createInput({ color: "indigo" })).success).toBe(
    80	      false,
    81	    );
    82	    expect(createProjectSchema.safeParse(createInput({ color: "#abc" })).success).toBe(
    83	      false,
    84	    );
    85	  });
    86	
    87	  it("bounds the name and description", () => {
    88	    expect(createProjectSchema.safeParse(createInput({ name: "W" })).success).toBe(false);
    89	    expect(
    90	      createProjectSchema.safeParse(createInput({ name: "a".repeat(81) })).success,
    91	    ).toBe(false);
    92	    expect(
    93	      createProjectSchema.safeParse(createInput({ description: "a".repeat(2_001) }))
    94	        .success,
    95	    ).toBe(false);
    96	  });
    97	
    98	  it("makes update fields optional but does not allow a slug or key change", () => {
    99	    const parsed = updateProjectSchema.parse({ orgId: ORG_A, projectId: PROJECT });
   100	    expect(parsed).toEqual({ orgId: ORG_A, projectId: PROJECT });
   101	    expect("slug" in parsed).toBe(false);
   102	    expect("key" in parsed).toBe(false);
   103	  });
   104	
   105	  it("defaults an archive to cascading over the project's issues", () => {
   106	    expect(archiveProjectSchema.parse({ orgId: ORG_A, projectId: PROJECT })).toEqual({
   107	      orgId: ORG_A,
   108	      projectId: PROJECT,
   109	      archiveIssues: true,
   110	    });
   111	    expect(
   112	      archiveProjectSchema.parse({
   113	        orgId: ORG_A,
   114	        projectId: PROJECT,
   115	        archiveIssues: false,
   116	      }).archiveIssues,
   117	    ).toBe(false);
   118	  });
   119	
   120	  it("extends the list schema with pagination and archive scope", () => {
   121	    const parsed = listProjectsSchema.parse({ orgId: ORG_A });
   122	    expect(parsed.limit).toBe(25);
   123	    expect(parsed.includeArchived).toBeUndefined();
   124	    expect(
   125	      listProjectsSchema.parse({ orgId: ORG_A, includeArchived: true }).includeArchived,
   126	    ).toBe(true);
   127	  });
   128	});

