/**
 * Writes a clone in one SQLite transaction: the project row, then each copied
 * issue with its labels, so a failure part-way leaves nothing behind. The slug
 * is made unique exactly as `insertProject` makes it. The body stays synchronous
 * because an `await` inside a transaction callback would let it commit early.
 */
export async function insertClonedProject(
  input: CreateProjectInput,
  copies: readonly ClonedIssue[],
): Promise<Project> {
  const taken = await listTakenProjectSlugs(input.orgId);
  const slug = uniqueSlug(input.slug, taken);
  const stamp = toIsoTimestamp(new Date());

  return getDb().transaction((tx) => {
    const row = tx
      .insert(projects)
      .values({
        id: newId(),
        orgId: input.orgId,
        name: input.name,
        slug,
        key: input.key,
        description: input.description,
        visibility: input.visibility,
        status: "active",
        leadId: input.leadId,
        color: input.color,
        startsAt: null,
        targetDate: input.targetDate,
        createdAt: stamp,
        updatedAt: stamp,
      })
      .returning()
      .get();

    for (const copy of copies) {
      const issueId = newId();
      tx.insert(issues)
        .values({
          id: issueId,
          orgId: input.orgId,
          projectId: row.id,
          number: copy.number,
          title: copy.title,
          description: copy.description,
          status: copy.status,
          priority: copy.priority,
          authorId: copy.authorId,
          assigneeId: null,
          parentId: null,
          estimate: copy.estimate,
          dueAt: copy.dueAt,
          startedAt: null,
          completedAt: null,
          createdAt: stamp,
          updatedAt: stamp,
        })
        .run();

      if (copy.labelIds.length > 0) {
        tx.insert(issueLabels)
          .values(
            copy.labelIds.map((labelId) => ({
              orgId: input.orgId,
              issueId,
              labelId,
            })),
          )
          .run();
      }
    }

    return toProject(row);
  });
}

