/**
 * Clones a project into the same workspace under the name, slug and key the
 * caller chose (ADR 0012). Every gate runs before anything is written: tenant
 * scope, `project:read` on the source, the source is live, `project:create` on
 * the workspace, the plan's project quota, then the issue quota for the whole
 * batch of copies. Copies are the live issues only, numbered from 1 in the
 * source's number order, and reset to the workspace's default status, unassigned
 * and authored by the caller. Comments, attachments and parent links are not copied.
 */
export async function cloneProject(
  actor: Actor,
  input: CloneProjectInput,
): Promise<Project> {
  assertOrgScope(actor, input.orgId);

  const source = requireFound(
    await projectRepo.findProjectById(input.orgId, input.projectId),
    "Project",
    input.projectId,
  );
  assertCan(actor, "project:read", projectResource(source));
  assertNotArchived("Project", source.id, source);
  assertCan(actor, "project:create", orgResource(input.orgId));

  const org = requireFound(
    await orgRepo.findOrgById(input.orgId),
    "Organization",
    input.orgId,
  );

  const usedProjects = await projectRepo.countProjects(input.orgId);
  if (wouldExceedLimit(org.plan, "projects", usedProjects)) {
    throw new Error(
      `Plan ${org.plan} allows ${usedProjects} projects; upgrade to add another`,
    );
  }

  const sourceIssues = input.includeIssues
    ? await issueRepo.listAllLiveIssues(input.orgId, source.id)
    : [];

  // The clone is brand new, so the whole batch is measured against an empty project.
  if (wouldExceedLimit(org.plan, "issuesPerProject", 0, sourceIssues.length)) {
    throw new Error(
      `Plan ${org.plan} allows ${getLimit(org.plan, "issuesPerProject")} issues per project; cloning would copy ${sourceIssues.length}`,
    );
  }

  const defaultStatus = defaultIssueStatusFor(org.settings.defaultIssueStatus);

  const project = await projectRepo.insertClonedProject(
    {
      orgId: input.orgId,
      name: input.name,
      slug: input.slug,
      key: input.key,
      description: source.description,
      visibility: source.visibility,
      leadId: source.leadId,
      color: source.color,
      // A clone starts with no target date, whatever the source had.
      targetDate: null,
    },
    sourceIssues.map((issue, index) => ({
      number: index + 1,
      title: issue.title,
      description: issue.description,
      status: defaultStatus,
      priority: issue.priority,
      authorId: actor.userId,
      estimate: issue.estimate,
      dueAt: issue.dueAt,
      labelIds: issue.labelIds,
    })),
  );

  await emit("project.cloned", {
    ...actorEnvelope(actor),
    projectId: project.id,
    sourceProjectId: source.id,
    issuesCopied: sourceIssues.length,
  });

  return project;
}

/** Same re-validation the new-issue form applies to the stored default status. */
function defaultIssueStatusFor(stored: string): IssueStatus {
  const parsed = issueStatusSchema.safeParse(stored);
  return parsed.success ? parsed.data : "backlog";
}

