/**
 * Cloning a project (ADR 0012): the gates, the copy rules, the single
 * `project.cloned` announcement and the reactions that stand in for the
 * per-copy announcements a clone does not publish.
 */
import { afterAll, afterEach, beforeAll, describe, expect, it, vi } from "vitest";

vi.mock("@/lib/id", () => import("../server/_support/doubles/id"));
vi.mock("@/lib/logger", async () => (await import("../server/_support/doubles/misc")).loggerModule);
vi.mock("@/lib/rate-limit", async () => (await import("../server/_support/doubles/misc")).rateLimitModule);

import { subscribe } from "@/lib/event-bus";
import { PermissionDeniedError } from "@/lib/permissions";
import * as commentRepo from "@/server/repositories/comment-repository";
import * as issueRepo from "@/server/repositories/issue-repository";
import * as labelRepo from "@/server/repositories/label-repository";
import * as orgRepo from "@/server/repositories/organization-repository";
import * as projectRepo from "@/server/repositories/project-repository";
import * as usageRepo from "@/server/repositories/usage-repository";
import * as activityService from "@/server/services/activity-service";
import * as commentService from "@/server/services/comment-service";
import * as issueService from "@/server/services/issue-service";
import * as projectService from "@/server/services/project-service";
import * as searchService from "@/server/services/search-service";
import { registerUsageListeners } from "@/server/services/usage-service";
import { createTenant, issueInput, useTemporaryDatabase } from "../server/_support/fixtures";
import type { Tenant } from "../server/_support/fixtures";
import type { CloneProjectInput } from "@/schemas/project";
import type { IsoTimestamp, OrgId, ProjectId } from "@/types/common";
import type { TaskflowEventMap, TaskflowEventType, Unsubscribe } from "@/types/event";

const DUE = "2026-12-31T00:00:00.000Z";
const TARGET = "2026-11-30T00:00:00.000Z" as IsoTimestamp;

let cleanup: () => void;
const persistent: Unsubscribe[] = [];
const scoped: Unsubscribe[] = [];

/** Collects every payload delivered for one event type until the test ends. */
function capture<K extends TaskflowEventType>(type: K): TaskflowEventMap[K][] {
  const seen: TaskflowEventMap[K][] = [];
  scoped.push(
    subscribe(type, (payload) => {
      seen.push(payload);
    }),
  );
  return seen;
}

function cloneInput(
  orgId: OrgId,
  projectId: ProjectId,
  overrides: Partial<CloneProjectInput> = {},
): CloneProjectInput {
  return {
    orgId,
    projectId,
    name: "Release Train Copy",
    slug: "release-train-copy",
    key: "RTC",
    includeIssues: true,
    ...overrides,
  };
}

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
  persistent.push(
    activityService.registerActivityListeners(),
    searchService.registerSearchListeners(),
    registerUsageListeners(),
  );
});

afterEach(() => {
  while (scoped.length > 0) scoped.pop()?.();
});

afterAll(() => {
  while (persistent.length > 0) persistent.pop()?.();
  cleanup();
});

describe("services/project-service cloneProject", () => {
  it("copies the source's shape under the chosen name, slug and key", async () => {
    const tenant = await createTenant("clonashape", "growth");
    const { org, project, actors, userIds } = tenant;

    await projectService.updateProject(actors.admin, {
      orgId: org.id,
      projectId: project.id,
      description: "Quarterly release train",
      visibility: "private",
      color: "#ff0000",
      targetDate: TARGET,
    });

    const clone = await projectService.cloneProject(
      actors.member,
      cloneInput(org.id, project.id, { name: "Release Train Copy" }),
    );

    expect(clone).toMatchObject({
      orgId: org.id,
      name: "Release Train Copy",
      slug: "release-train-copy",
      key: "RTC",
      description: "Quarterly release train",
      visibility: "private",
      color: "#ff0000",
      leadId: userIds.owner,
      status: "active",
      startsAt: null,
      targetDate: null,
      archivedAt: null,
    });
    expect(clone.id).not.toBe(project.id);
    expect(await projectRepo.findProjectById(org.id, clone.id)).toMatchObject({
      id: clone.id,
      targetDate: null,
    });
  });

  it("suffixes the slug when the chosen one is already taken", async () => {
    // `createTenant` seeds a project slugged "platform".
    const tenant = await createTenant("clonaslug", "growth");

    const clone = await projectService.cloneProject(
      tenant.actors.member,
      cloneInput(tenant.org.id, tenant.project.id, {
        name: "Platform Copy",
        slug: "platform",
        key: "PCP",
      }),
    );

    expect(clone.slug).toBe("platform-2");
  });

  it("copies live issues renumbered from 1, reset to the default status and unassigned", async () => {
    const tenant = await createTenant("clonarules", "growth");
    const { org, project, actors, userIds } = tenant;

    const first = await issueService.createIssue(
      actors.member,
      issueInput(org.id, project.id, {
        title: "First issue",
        assigneeId: userIds.member,
      }),
    );
    const archived = await issueService.createIssue(
      actors.member,
      issueInput(org.id, project.id, { title: "Archived issue" }),
    );
    const third = await issueService.createIssue(
      actors.member,
      issueInput(org.id, project.id, { title: "Third issue", dueAt: DUE }),
    );

    await issueService.updateIssue(actors.member, {
      orgId: org.id,
      issueId: first.id,
      priority: "high",
      estimate: 3,
    });
    await issueService.archiveIssue(actors.member, org.id, archived.id);
    await issueService.changeIssueStatus(actors.member, {
      orgId: org.id,
      issueId: third.id,
      status: "in_progress",
    });

    const clone = await projectService.cloneProject(
      actors.admin,
      cloneInput(org.id, project.id, { name: "Rules Copy", slug: "rules-copy", key: "RUL" }),
    );

    const copies = await issueRepo.listAllLiveIssues(org.id, clone.id);
    expect(copies.map((issue) => [issue.number, issue.title])).toEqual([
      [1, "First issue"],
      [2, "Third issue"],
    ]);
    for (const copy of copies) {
      expect(copy).toMatchObject({
        status: "backlog",
        assigneeId: null,
        authorId: userIds.admin,
        startedAt: null,
        completedAt: null,
        parentId: null,
      });
    }
    expect(copies[0]).toMatchObject({ priority: "high", estimate: 3 });
    expect(copies[1]?.dueAt).toBe(DUE);

    // The source keeps its own numbers, statuses and assignees.
    const sourceLive = await issueRepo.listAllLiveIssues(org.id, project.id);
    expect(sourceLive.map((issue) => issue.number)).toEqual([1, 3]);
    expect(await issueRepo.findIssueById(org.id, third.id)).toMatchObject({
      status: "in_progress",
      assigneeId: null,
    });
    expect(await issueRepo.findIssueById(org.id, first.id)).toMatchObject({
      assigneeId: userIds.member,
    });
  });

  it("starts copies in the workspace's default issue status", async () => {
    const tenant = await createTenant("clonadefault", "growth");
    await orgRepo.updateOrg(tenant.org.id, {
      settings: { defaultIssueStatus: "todo" },
    });
    await issueService.createIssue(
      tenant.actors.member,
      issueInput(tenant.org.id, tenant.project.id, { title: "Start in todo" }),
    );

    const clone = await projectService.cloneProject(
      tenant.actors.member,
      cloneInput(tenant.org.id, tenant.project.id, {
        name: "Default Copy",
        slug: "default-copy",
        key: "DFC",
      }),
    );

    const copies = await issueRepo.listAllLiveIssues(tenant.org.id, clone.id);
    expect(copies.map((issue) => issue.status)).toEqual(["todo"]);
  });

  it("keeps labels on the copies but not comments, and leaves the source alone", async () => {
    const tenant = await createTenant("clonalabels", "growth");
    const { org, project, actors } = tenant;

    const label = await labelRepo.insertLabel({
      orgId: org.id,
      name: "Blocker",
      color: "#ff0000",
      description: null,
    });
    const issue = await issueService.createIssue(
      actors.member,
      issueInput(org.id, project.id, { title: "Labelled issue" }),
    );
    await issueService.updateIssue(actors.member, {
      orgId: org.id,
      issueId: issue.id,
      labelIds: [label.id],
    });
    await commentService.createComment(actors.member, {
      orgId: org.id,
      issueId: issue.id,
      body: "Looks good",
      parentId: null,
      mentionedUserIds: [],
    });

    const clone = await projectService.cloneProject(
      actors.member,
      cloneInput(org.id, project.id, { name: "Label Copy", slug: "label-copy", key: "LBC" }),
    );

    const [copy] = await issueRepo.listAllLiveIssues(org.id, clone.id);
    expect(copy?.labelIds).toEqual([label.id]);
    expect(await commentRepo.countComments(org.id, copy?.id as never)).toBe(0);

    expect(await commentRepo.countComments(org.id, issue.id)).toBe(1);
    expect(await issueRepo.findIssueById(org.id, issue.id)).toMatchObject({
      labelIds: [label.id],
      status: "backlog",
    });
  });

  it("copies every live issue, not only the first page", async () => {
    const tenant = await createTenant("clonabig", "growth");
    const total = 130;

    // Seeded through the repository: 130 service calls would only slow the suite down.
    for (let number = 1; number <= total; number += 1) {
      await issueRepo.insertIssue(
        issueInput(tenant.org.id, tenant.project.id, { title: `Bulk issue ${number}` }),
        tenant.userIds.member,
        number,
      );
    }

    const seen = capture("project.cloned");
    const clone = await projectService.cloneProject(
      tenant.actors.member,
      cloneInput(tenant.org.id, tenant.project.id, {
        name: "Big Copy",
        slug: "big-copy",
        key: "BIG",
      }),
    );

    const copies = await issueRepo.listAllLiveIssues(tenant.org.id, clone.id);
    expect(copies).toHaveLength(total);
    expect(copies.map((issue) => issue.number)).toEqual(
      Array.from({ length: total }, (_, index) => index + 1),
    );
    expect(seen[0]).toMatchObject({ projectId: clone.id, issuesCopied: total });
  });

  it("copies only the project when includeIssues is false", async () => {
    const tenant = await createTenant("clonanoissues", "growth");
    await issueService.createIssue(
      tenant.actors.member,
      issueInput(tenant.org.id, tenant.project.id, { title: "Left behind" }),
    );

    const seen = capture("project.cloned");
    const clone = await projectService.cloneProject(
      tenant.actors.member,
      cloneInput(tenant.org.id, tenant.project.id, {
        name: "Empty Copy",
        slug: "empty-copy",
        key: "EMP",
        includeIssues: false,
      }),
    );

    expect(await issueRepo.listAllLiveIssues(tenant.org.id, clone.id)).toHaveLength(0);
    expect(seen).toEqual([
      expect.objectContaining({ projectId: clone.id, sourceProjectId: tenant.project.id, issuesCopied: 0 }),
    ]);
  });

  it("is refused, with nothing written, when the copies would exceed the plan's issue quota", async () => {
    // The free plan allows 100 issues per project; the service would refuse a 101st, so the rows are seeded directly.
    const tenant = await createTenant("clonaquota", "free");
    for (let number = 1; number <= 101; number += 1) {
      await issueRepo.insertIssue(
        issueInput(tenant.org.id, tenant.project.id, { title: `Quota issue ${number}` }),
        tenant.userIds.member,
        number,
      );
    }

    const projectsBefore = await projectRepo.countProjects(tenant.org.id);
    const seen = capture("project.cloned");

    await expect(
      projectService.cloneProject(
        tenant.actors.admin,
